#!/usr/bin/env bash
# List hex colors in app source that are not NES palette tokens.
# Usage: audit-colors.sh [path]   (default: apps/mobile/src)
set -euo pipefail
root="$(git rev-parse --show-toplevel)"
target="${1:-$root/apps/mobile/src}"
allowed='000000|101010|2A2A2A|3A3A3A|A5ACAF|8A6410|FCFCFC|BCBCBC|7C7C7C|F8B800|F8D878|58D854|007800|F83800|A81000|3CBCFC|D8B8F8|FCA044|A4E4FC|F0D0B0'
# Logo art only: the app logo (src/components/pixel/logoArt.ts, generated by icons.py) uses extra
# colors: the rays' official Pantone team colors (Lakers purple and gold, Dodger blue) and NES
# dark gold, bun orange, lettuce and patty. They are allowed in that one file, never in UI.
logo='552583|FDB927|005A9C|AC7C00|E45C10|00A800|881400'
hits="$(grep -rnoiE "#[0-9a-f]{6}\b|#[0-9a-f]{3}\b" "$target" --include='*.ts' --include='*.tsx' --exclude='*.test.ts' --exclude='*.test.tsx' \
  | grep -viE "#($allowed)\b" \
  | grep -viE "/logoArt\.ts:[0-9]+:#($logo)\b" || true)"
if [[ -z "$hits" ]]; then echo "ok: only NES tokens"; exit 0; fi
echo "$hits"
echo "$(echo "$hits" | wc -l | tr -d ' ') non-token color(s): move them to theme tokens (useTheme.tsx is the one allowed place for raw hex)." >&2
exit 1
